from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives import padding
import json

KEY = bytes(32)  # demo only

# MISUSE: decrypt first, then report WHICH step failed.
def handle_cookie(blob: bytes):
    dec = Cipher(algorithms.AES(KEY), modes.CBC(blob[:16])).decryptor()
    padded = dec.update(blob[16:]) + dec.finalize()
    u = padding.PKCS7(128).unpadder()
    try:
        data = u.update(padded) + u.finalize()
    except ValueError:
        return 400, "bad padding"        # answer 1
    try:
        return 200, json.loads(data)
    except ValueError:
        return 400, "bad json"           # answer 2: different!

def eq_early(a, b):
    for i in range(len(a)):
        if a[i] != b[i]:
            return False
    return True

def eq_const(a, b):
    diff = 0
    for i in range(len(a)):
        diff |= a[i] ^ b[i]
    return diff == 0

#include <stdio.h>
#include <string.h>

/* MISUSE for secrets: memcmp may return at the first difference. */
int tag_ok_bad(const unsigned char *a, const unsigned char *b, size_t n) {
    return memcmp(a, b, n) == 0;
}

/* CORRECT: always touches every byte; no branch on secret data. */
int tag_ok(const unsigned char *a, const unsigned char *b, size_t n) {
    unsigned char diff = 0;
    for (size_t i = 0; i < n; i++)
        diff |= a[i] ^ b[i];        /* stays 0 only if all bytes match */
    return diff == 0;
}

int main(void) {
    unsigned char t[4] = {0xde, 0xad, 0xbe, 0xef};
    unsigned char g[4] = {0xde, 0xad, 0x00, 0xef};
    printf("%d %d\n", tag_ok(t, t, 4), tag_ok(t, g, 4));   /* 1 0 */
    return 0;
}

