import hashlib
from collections import defaultdict

def fingerprint(public_key_der: bytes) -> str:
    return hashlib.sha256(public_key_der).hexdigest()[:16]

def shared_keys(inventory):
    """inventory: {hostname: public key bytes} collected from your fleet.
    Two devices with the same key usually means a factory default key or
    a generator that ran with too little entropy."""
    by_fp = defaultdict(list)
    for host, der in inventory.items():
        by_fp[fingerprint(der)].append(host)
    return {fp: hosts for fp, hosts in by_fp.items() if len(hosts) > 1}

fleet = {"cam-01": b"keyA", "cam-02": b"keyA", "router-1": b"keyB"}
print(shared_keys(fleet))   # {'8a197f6f60e55bf2': ['cam-01', 'cam-02']}

import hashlib, hmac, json, secrets, time

KEY = secrets.token_bytes(32)

# MISUSE 1: a hash of secret || message (length extension with SHA-2/MD5)
# MISUSE 2: gluing fields together with no boundaries, so two different
# requests can produce the same signed string
def sign_bad(params: dict) -> str:
    s = "".join(k + v for k, v in sorted(params.items()))
    return hashlib.sha256(KEY + s.encode()).hexdigest()

# CORRECT: HMAC over an unambiguous encoding that also carries
# a purpose label, a key id and a timestamp
def canonical(params: dict, ts: int) -> bytes:
    return json.dumps({"v": "api-sig-1", "kid": "k1", "ts": ts,
                       "p": params}, sort_keys=True,
                      separators=(",", ":")).encode()

def sign(params: dict, ts: int) -> str:
    return hmac.new(KEY, canonical(params, ts), hashlib.sha256).hexdigest()

def verify(params, ts, sig, now, max_age=300) -> bool:
    if abs(now - ts) > max_age:
        return False                      # stale: refuse replays
    return hmac.compare_digest(sign(params, ts), sig)

now = int(time.time())
sig = sign({"photo": "123", "perm": "read"}, now)
print(verify({"photo": "123", "perm": "read"}, now, sig, now))   # True
print(verify({"photo": "123", "perm": "write"}, now, sig, now))  # False

# Also correct: keyed BLAKE2b, safe in prefix-MAC mode
print(len(hashlib.blake2b(b"msg", key=KEY, digest_size=32).digest()))  # 32

import os, pytest
from cryptography.fernet import Fernet, InvalidToken
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from cryptography.exceptions import InvalidTag

# Tests that pin down CORRECT use of the crypto in our own code.
key = AESGCM.generate_key(bit_length=256)

def seal(pt, aad):                    # the function under test
    n = os.urandom(12)
    return n + AESGCM(key).encrypt(n, pt, aad)

def unseal(blob, aad):
    return AESGCM(key).decrypt(blob[:12], blob[12:], aad)

def test_round_trip():
    assert unseal(seal(b"hi", b"u1"), b"u1") == b"hi"

def test_every_bit_flip_is_rejected():
    blob = seal(b"hi", b"u1")
    for i in range(len(blob) * 8):
        bad = bytearray(blob); bad[i // 8] ^= 1 << (i % 8)
        with pytest.raises(InvalidTag):
            unseal(bytes(bad), b"u1")

def test_wrong_context_is_rejected():
    with pytest.raises(InvalidTag):
        unseal(seal(b"hi", b"u1"), b"u2")

def test_nonces_do_not_repeat():
    nonces = {seal(b"x", b"")[:12] for _ in range(10_000)}
    assert len(nonces) == 10_000

def test_fernet_rejects_old_tokens():
    f = Fernet(Fernet.generate_key())
    token = f.encrypt_at_time(b"reset", current_time=1_000)
    with pytest.raises(InvalidToken):
        f.decrypt_at_time(token, ttl=300, current_time=2_000)

# $ python -m pytest -q test_crypto_use.py
# .....   5 passed

